  get:(id,opt,cb)=>{const w=managedWins.get(id),u=managedWinUrls.get(id)||'',x=w&&!w.closed?{id,left:w.screenX||0,top:w.screenY||0,width:w.outerWidth||640,height:w.outerHeight||500,tabs:[{url:u}]}:null;if(cb)cb(x);return Promise.resolve(x)},
  getAll:(opt,cb)=>{const a=[];for(const [id,w] of managedWins)if(w&&!w.closed)a.push({id,left:w.screenX||0,top:w.screenY||0,width:w.outerWidth||640,height:w.outerHeight||500,tabs:[{url:managedWinUrls.get(id)||''}]});if(cb)cb(a);return Promise.resolve(a)},
  update:(id,o,cb)=>{const w=managedWins.get(id);try{if(w){if(o.focused)w.focus();if(Number.isFinite(o.left)&&Number.isFinite(o.top))w.moveTo(o.left,o.top);if(Number.isFinite(o.width)&&Number.isFinite(o.height))w.resizeTo(o.width,o.height)}}catch(e){}const x={id};if(cb)cb(x);return Promise.resolve(x)},
